stylesheets.stylesheet:
/* ===== I-Forge RPG - Brutalist Manga Theme ===== */
@import url('https://fonts.googleapis.com/css2?family=Permanent+Marker&display=swap');

:root {
  --bg: #f4f0e6;
  --bg-dark: #ebe6d6;
  --panel: #2d5a27;
  --panel-hover: #3d7a35;
  --gold: #c9a84c;
  --gold-hover: #e2c96b;
  --ink: #1a1a1a;
  --ink-secondary: #5a5a4a;
  --border: #1e3d1a;
  --shadow: 3px 3px 0 #1e3d1a;
  --shadow-hover: 4px 4px 0 #1e3d1a;
  --radius: 3px;
  --font-brush: 'Permanent Marker', 'Comic Sans MS', 'Chalkboard SE', cursive;
  --font-serif: Georgia, 'Palatino Linotype', 'Times New Roman', serif;
  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  background: var(--bg) !important;
  color: var(--ink) !important;
  font-family: var(--font-serif) !important;
  font-size: 15px;
  line-height: 1.5;
}
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background-image: repeating-linear-gradient(
    0deg,
    rgba(30, 61, 26, 0.04) 0px,
    rgba(30, 61, 26, 0.04) 1px,
    transparent 1px,
    transparent 24px
  );
  pointer-events: none;
  z-index: -1;
}
body { padding-top: 56px; }

img.icon { width: 14px; height: 14px; vertical-align: middle; }
img { max-width: 100%; height: auto; }

a, a:link, a:visited { color: var(--gold); text-decoration: none; font-weight: 600; transition: color 0.15s; }
a:hover, a:active, a:focus { color: var(--gold-hover); }

/* Hide MyBB clutter */
#header, #logo, #panel, .welcomeblock, .upper, .modal,
.navigation, #footer, .bottom_links, .theme, #theme_select,
#copyright, .lower, #debug {
  display: none !important;
}

#container, #content, .content, .container, .wrapper, #wrapper, #main {
  background: transparent !important;
  max-width: none !important;
  width: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
}

/* MyBB table defaults */
.tborder, .tcat, .thead, .trow1, .trow2, tbody, .panel, .post, .post_content, .postbit, #posts, .pagination, .forumdisplay, .threadlist {
  background: transparent !important;
  border-color: var(--border) !important;
}
.tcat, .thead {
  background: var(--panel) !important;
  color: var(--gold) !important;
  border: 3px solid var(--border) !important;
  box-shadow: var(--shadow) !important;
}
.tborder { border: 3px solid var(--border) !important; }

/* Navbar fixed - outside container */
#iforge-navbar {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  z-index: 10000 !important;
  background: var(--panel);
  border-bottom: 3px solid var(--border);
  box-shadow: var(--shadow);
}
.iforge-nav {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 56px;
  padding: 0 16px;
  position: relative;
}
.iforge-nav-left { display: flex; align-items: center; gap: 24px; }
.iforge-nav-logo {
  position: absolute;
  left: 16px;
  font-family: var(--font-brush);
  font-size: 1.4rem;
  color: var(--gold);
  letter-spacing: 2px;
  text-transform: uppercase;
  text-shadow: 2px 2px 0 var(--border);
}
.iforge-nav-logo:hover { color: var(--gold-hover); }
.iforge-nav-link {
  color: #fff;
  font-family: var(--font-sans);
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 4px 0;
  position: relative;
}
.iforge-nav-link:hover { color: var(--gold-hover); }
.iforge-nav-link::after {
  content: '';
  position: absolute;
  bottom: -4px; left: 0; right: 0;
  height: 3px;
  background: var(--gold);
  transform: scaleX(0);
  transition: transform 0.2s;
}
.iforge-nav-link:hover::after { transform: scaleX(1); }
.iforge-nav-right { position: absolute; right: 16px; }
.iforge-user-btn {
  background: var(--panel-hover);
  border: 3px solid var(--border);
  border-radius: 50%;
  width: 36px; height: 36px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gold);
  font-weight: 700;
  box-shadow: 2px 2px 0 var(--border);
}
.iforge-user-btn:hover { background: var(--gold); color: var(--panel); }
.iforge-dropdown {
  display: none;
  position: absolute;
  right: 0; top: 46px;
  background: var(--bg-dark);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  min-width: 180px;
  overflow: hidden;
}
.iforge-dropdown.open { display: block; }
.iforge-dropdown-item {
  display: block;
  padding: 8px 14px;
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 0.8rem;
  font-weight: 600;
  border-bottom: 2px solid var(--border);
  transition: background 0.15s;
}
.iforge-dropdown-item:last-child { border-bottom: none; }
.iforge-dropdown-item:hover { background: var(--gold); color: var(--panel); }
.iforge-dropdown-divider { border: none; border-top: 2px solid var(--border); margin: 0; }

/* Banner */
#iforge-banner {
  position: relative;
  width: 100%;
  height: 300px;
  overflow: hidden;
  background-size: cover;
  background-position: center;
  border-bottom: 3px solid var(--border);
  box-shadow: var(--shadow);
  display: flex;
  align-items: center;
  justify-content: center;
}
#iforge-banner::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(244,240,230,0.25) 0%, rgba(30,61,26,0.6) 100%);
}
.iforge-banner-seal {
  position: absolute;
  z-index: 1;
  color: rgba(30,61,26,0.14);
  font-size: 200px;
  pointer-events: none;
  font-family: var(--font-brush);
  user-select: none;
  letter-spacing: 4px;
}
.iforge-banner-content { position: relative; z-index: 2; text-align: center; }
.iforge-banner-title {
  font-family: var(--font-brush);
  font-size: 3rem;
  color: var(--gold);
  letter-spacing: 5px;
  text-transform: uppercase;
  text-shadow: 3px 3px 0 var(--border), -1px -1px 0 rgba(255,255,255,0.3);
  margin-bottom: 6px;
}
.iforge-banner-subtitle {
  font-family: var(--font-serif);
  font-size: 1rem;
  color: #fff;
  letter-spacing: 3px;
  font-weight: 700;
  text-shadow: 2px 2px 0 var(--border);
}

/* Calendar bar */
#iforge-calendar-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--panel);
  border-bottom: 3px solid var(--border);
  box-shadow: var(--shadow);
  font-family: var(--font-sans);
  font-size: 0.78rem;
  color: #fff;
  letter-spacing: 1px;
  text-transform: uppercase;
  font-weight: 700;
  cursor: pointer;
}
#iforge-calendar-bar:hover { background: var(--panel-hover); }
#iforge-calendar-bar .icon { width: 14px; height: 14px; filter: brightness(0) invert(1); }
#iforge-calendar-bar strong { color: var(--gold); }

/* ===== TABLON ===== */
.iforge-tablon {
  max-width: 1200px;
  margin: 12px auto 0;
  padding: 0 16px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}
.iforge-tablon-col {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
  height: 100%;
}
.iforge-tablon-title {
  font-family: var(--font-brush);
  font-size: 1.75rem;
  color: var(--panel);
  text-transform: uppercase;
  line-height: 1;
  margin-bottom: 0;
  letter-spacing: 1px;
  text-shadow: 2px 2px 0 var(--gold);
  word-break: break-word;
}
.iforge-tablon-title span {
  display: block;
  color: var(--gold);
  text-shadow: 2px 2px 0 var(--panel);
}
.iforge-tablon-box {
  background: var(--bg-dark);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 140px;
}
.iforge-tablon-box-header {
  padding: 8px 12px;
  font-family: var(--font-brush);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--gold);
  background: var(--panel);
  border-bottom: 3px solid var(--border);
}
.iforge-tablon-box-body {
  padding: 8px 10px;
  flex: 1;
}
.iforge-tablon-box-body:empty::after {
  content: 'Vacío por ahora...';
  display: block;
  color: var(--ink-secondary);
  font-style: italic;
  text-align: center;
  padding: 16px 0;
}
.iforge-card-item {
  display: block;
  padding: 6px 0;
  border-bottom: 2px dashed var(--border);
  color: var(--ink);
  font-size: 0.85rem;
  font-weight: 600;
}
.iforge-card-item:last-child { border-bottom: none; }
.iforge-card-item-meta {
  font-size: 0.72rem;
  color: var(--ink-secondary);
  font-family: var(--font-sans);
  margin-top: 2px;
}
.iforge-ambientacion {
  background: var(--panel);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  padding: 14px;
  color: #fff;
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 140px;
}
.iforge-ambientacion-label {
  font-family: var(--font-sans);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gold);
  margin-bottom: 2px;
}
.iforge-ambientacion-title {
  font-family: var(--font-brush);
  font-size: 1.5rem;
  color: var(--gold);
  text-transform: uppercase;
  margin-bottom: 8px;
  letter-spacing: 1px;
  text-shadow: 2px 2px 0 var(--border);
}
.iforge-ambientacion-text {
  font-size: 0.85rem;
  line-height: 1.5;
  color: #fff !important;
  flex: 1;
}
.iforge-lore-btn {
  display: inline-block;
  align-self: flex-start;
  margin-top: 10px;
  padding: 6px 12px;
  background: var(--gold);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--panel);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  text-align: center;
  transition: background 0.15s, transform 0.15s;
}
.iforge-lore-btn:hover {
  background: var(--gold-hover);
  transform: translateY(-1px);
}
.iforge-quick-links {
  background: var(--bg-dark);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  padding: 10px;
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 140px;
}
.iforge-quick-links-title {
  font-family: var(--font-brush);
  font-size: 0.9rem;
  color: var(--panel);
  text-transform: uppercase;
  margin-bottom: 8px;
  letter-spacing: 1px;
}
.iforge-quick-links-body {
  font-size: 0.85rem;
  line-height: 1.5;
  color: var(--ink);
  font-style: italic;
  margin-bottom: 8px;
}
#iforge-next-curiosidad {
  display: inline-block;
  align-self: flex-start;
  margin-top: auto;
  padding: 5px 12px;
  background: var(--gold);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.7rem;
  font-weight: 800;
  color: var(--panel);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: background 0.15s, transform 0.15s;
}
#iforge-next-curiosidad:hover {
  background: var(--gold-hover);
  transform: translateY(-1px);
}

/* Tabs */
.iforge-tabs {
  display: flex;
  gap: 6px;
}
.iforge-tab {
  flex: 1;
  padding: 8px 4px;
  background: var(--panel);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  color: #fff;
  font-family: var(--font-brush);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: background 0.15s;
}
.iforge-tab:hover, .iforge-tab.active {
  background: var(--gold);
  color: var(--panel);
}

#iforge-next-curiosidad {
  cursor: pointer;
  color: var(--panel);
  display: inline-block;
  margin-top: 6px;
  font-size: 0.75rem;
  font-family: var(--font-sans);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 10px;
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  transition: background 0.15s;
}
#iforge-next-curiosidad:hover { background: var(--gold); color: var(--panel); }

/* Staff */
.iforge-staff-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 10px;
}
.iforge-staff-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  background: var(--bg);
  border: 3px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-size: 0.8rem;
  font-family: var(--font-sans);
  font-weight: 600;
}
.iforge-staff-mp {
  color: var(--ink-secondary);
  font-size: 0.7rem;
  padding: 2px 6px;
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-weight: 700;
}
.iforge-staff-mp:hover { background: var(--gold); color: var(--panel); }

/* ===== CATEGORIES WITH FORUMS ===== */
.iforge-categories {
  max-width: 1200px;
  margin: 0 auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.iforge-category-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.iforge-category-section-header {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 14px;
  background: var(--panel);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
}
.iforge-category-section-title {
  font-family: var(--font-brush);
  font-size: 1.4rem;
  color: var(--gold);
  text-transform: uppercase;
  letter-spacing: 1.5px;
  line-height: 1.1;
  margin: 0;
  text-shadow: 2px 2px 0 var(--border);
}
.iforge-category-section-desc {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  color: #fff;
  opacity: 0.85;
  margin: 0;
}
.iforge-forums-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: stretch;
}
.iforge-forum-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  flex: 0 0 280px;
  max-width: 100%;
  min-height: 140px;
  padding: 14px;
  background: var(--panel);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  color: #fff;
  text-decoration: none;
  transition: transform 0.15s, border-color 0.15s, box-shadow 0.15s;
  overflow: hidden;
  word-break: break-word;
  overflow-wrap: anywhere;
}
.iforge-forum-card:hover {
  transform: translateY(-2px);
  border-color: var(--gold);
  box-shadow: var(--shadow-hover);
}
.iforge-forum-card-body {
  flex: 1;
}
.iforge-forum-card-title-link {
  text-decoration: none;
}
.iforge-forum-card-title-link:hover .iforge-forum-card-title {
  color: var(--gold-hover);
}
.iforge-forum-card-title {
  font-family: var(--font-brush);
  font-size: 1.1rem;
  color: var(--gold);
  text-transform: uppercase;
  letter-spacing: 0.8px;
  margin: 0 0 6px;
  line-height: 1.15;
}
.iforge-forum-card-desc {
  font-family: var(--font-sans);
  font-size: 0.78rem;
  color: rgba(255,255,255,0.85);
  line-height: 1.35;
  margin: 0 0 10px;
}
.iforge-forum-last {
  font-family: var(--font-sans);
  font-size: 0.72rem;
  color: rgba(255,255,255,0.7);
  line-height: 1.35;
}
.iforge-forum-last a {
  color: var(--gold-hover);
  font-weight: 600;
}
.iforge-forum-last a:hover {
  text-decoration: underline;
}
.iforge-forum-last-label {
  color: var(--gold);
  font-weight: 700;
}
.iforge-forum-card-stats {
  display: flex;
  gap: 12px;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 2px dashed rgba(244,240,230,0.25);
  font-family: var(--font-sans);
  font-size: 0.72rem;
  color: rgba(255,255,255,0.7);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.iforge-forum-stat strong {
  color: var(--gold);
  font-size: 0.85rem;
  margin-right: 2px;
}

/* Footer */
#iforge-footer {
  background: var(--panel);
  border-top: 3px solid var(--border);
  box-shadow: var(--shadow);
  padding: 16px;
  text-align: center;
  color: #fff;
  font-size: 0.75rem;
  font-family: var(--font-sans);
  font-weight: 600;
  letter-spacing: 0.5px;
  margin-top: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}
#iforge-footer .seal { width: 18px; height: 18px; opacity: 0.6; filter: brightness(0) invert(1); }
#iforge-footer a { color: var(--gold); }
#iforge-footer a:hover { color: var(--gold-hover); }

/* Badges */
.iforge-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 3px;
  font-size: 0.65rem;
  font-weight: 800;
  margin-right: 4px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  font-family: var(--font-sans);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
}

/* Responsive */
@media (max-width: 900px) {
  .iforge-tablon { grid-template-columns: 1fr; }
  .iforge-banner-title { font-size: 2.2rem; }
  #iforge-banner { height: 220px; }
  .iforge-nav-left { gap: 14px; }
  .iforge-nav-link { font-size: 0.72rem; }
}
@media (max-width: 600px) {
  .iforge-banner-title { font-size: 1.8rem; }
  .iforge-tablon-title { font-size: 1.6rem; }
  .iforge-nav { padding: 0 10px; }
  .iforge-nav-logo { font-size: 1.1rem; left: 10px; }
  .iforge-nav-right { right: 10px; }
  .iforge-quick-links-grid { grid-template-columns: 1fr; }
}

/* ===== FORUM DISPLAY ===== */
.iforge-forum-container { max-width: 1200px; margin: 0 auto; padding: 16px; }
.iforge-threadlist { display: flex; flex-direction: column; gap: 8px; }
.iforge-threadlist-toolbar { display: flex; justify-content: space-between; align-items: center; padding: 8px 12px; background: var(--panel); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); }
.iforge-threadlist-sort { font-family: var(--font-sans); font-size: 0.78rem; color: var(--gold); text-transform: uppercase; font-weight: 700; }
.iforge-threadlist-sort select, .iforge-threadlist-sort a { color: #fff; }
.iforge-newthread-btn { padding: 6px 14px; background: var(--gold); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-family: var(--font-brush); font-size: 0.85rem; color: var(--panel); text-transform: uppercase; letter-spacing: 1px; text-decoration: none; transition: background 0.15s, transform 0.15s; }
.iforge-newthread-btn:hover { background: var(--gold-hover); transform: translateY(-1px); }
.iforge-threadlist-pagination-top, .iforge-threadlist-pagination-bottom { display: flex; justify-content: center; padding: 4px 0; }
.iforge-threadlist-pagination-top .pagination, .iforge-threadlist-pagination-bottom .pagination { display: flex; gap: 4px; font-family: var(--font-sans); font-size: 0.75rem; }
.iforge-threadlist-pagination-top .pagination a, .iforge-threadlist-pagination-bottom .pagination a { padding: 4px 8px; background: var(--bg-dark); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); color: var(--ink); font-weight: 700; }
.iforge-threadlist-pagination-top .pagination .pagination_current, .iforge-threadlist-pagination-bottom .pagination .pagination_current { padding: 4px 8px; background: var(--panel); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); color: var(--gold); font-weight: 800; }
.iforge-threads { display: flex; flex-direction: column; gap: 6px; }
.iforge-thread-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 10px 14px; background: var(--bg-dark); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); transition: transform 0.15s, border-color 0.15s; }
.iforge-thread-row:hover { transform: translateY(-1px); border-color: var(--gold); }
.iforge-thread-main { display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0; }
.iforge-thread-icon { flex-shrink: 0; width: 20px; height: 20px; display: flex; align-items: center; }
.iforge-thread-icon img { width: 20px; height: 20px; }
.iforge-thread-info { min-width: 0; }
.iforge-thread-title { display: block; font-family: var(--font-sans); font-size: 0.9rem; color: var(--panel); font-weight: 700; text-decoration: none; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.iforge-thread-title:hover { color: var(--gold); }
.iforge-thread-meta { display: block; font-family: var(--font-sans); font-size: 0.7rem; color: var(--ink-secondary); margin-top: 2px; }
.iforge-thread-stats { display: flex; align-items: center; gap: 16px; flex-shrink: 0; font-family: var(--font-sans); font-size: 0.72rem; color: var(--ink-secondary); text-transform: uppercase; letter-spacing: 0.5px; }
.iforge-thread-replies strong { color: var(--panel); font-size: 0.85rem; }
.iforge-thread-lastpost { display: flex; flex-direction: column; align-items: flex-end; font-size: 0.7rem; }
.iforge-thread-lastpost a { color: var(--gold); font-weight: 600; }
.iforge-thread-lastpost a:hover { color: var(--gold-hover); }
.iforge-thread-last-label { color: var(--ink); font-weight: 700; font-size: 0.65rem; }
.iforge-subforums { padding: 4px 14px 8px; }
.iforge-subforums-label { font-family: var(--font-sans); font-size: 0.65rem; color: var(--ink-secondary); text-transform: uppercase; font-weight: 700; }
.iforge-subforums-grid { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; }
.iforge-threadlist-toolbar-bottom { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 8px 0; }
.iforge-announcements { display: flex; flex-direction: column; gap: 4px; margin-bottom: 6px; }
.iforge-announcements-header { font-family: var(--font-brush); font-size: 0.85rem; color: var(--gold); text-transform: uppercase; letter-spacing: 1px; padding: 6px 14px; background: var(--panel); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); }
.iforge-announcement-row { padding: 8px 14px; background: rgba(201,168,76,0.1); border: 3px solid var(--gold); box-shadow: var(--shadow); border-radius: var(--radius); }
.iforge-announcement-row a { color: var(--gold); font-weight: 700; font-family: var(--font-sans); font-size: 0.85rem; }
.iforge-announcement-row .iforge-thread-meta { color: rgba(255,255,255,0.7); }
.iforge-threadlist-sort form { display: inline; }
.iforge-threadlist-sort select { background: var(--panel-hover); color: #fff; border: 2px solid var(--border); font-family: var(--font-sans); font-size: 0.7rem; font-weight: 700; text-transform: uppercase; padding: 2px 4px; border-radius: var(--radius); }
.iforge-threadlist-sort .smalltext { color: var(--gold); }
.iforge-threadlist-sort .smalltext a { color: var(--gold-hover); font-weight: 700; }
.iforge-threadlist-toolbar-bottom form { display: inline; }
.iforge-threadlist-toolbar-bottom input.textbox { padding: 4px 8px; border: 2px solid var(--border); border-radius: var(--radius); background: var(--bg-dark); font-family: var(--font-sans); font-size: 0.72rem; color: var(--ink); box-shadow: 2px 2px 0 var(--border); }
@media (max-width: 700px) { .iforge-thread-row { flex-direction: column; align-items: flex-start; } .iforge-thread-stats { width: 100%; justify-content: space-between; } .iforge-threadlist-toolbar { flex-direction: column; gap: 8px; } }

/* ===== THREAD VIEW ===== */
.iforge-thread-container { max-width: 1200px; margin: 12px auto 0; padding: 0 16px 16px; display: flex; flex-direction: column; gap: 12px; }
.iforge-thread-header { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; padding: 14px; background: var(--panel); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); }
.iforge-thread-header .iforge-thread-title { font-family: var(--font-brush); font-size: 1.4rem; color: var(--gold); text-transform: uppercase; letter-spacing: 1px; line-height: 1.15; margin: 0; text-shadow: 2px 2px 0 var(--border); }
.iforge-thread-header-actions { font-family: var(--font-sans); font-size: 0.7rem; }
.iforge-thread-header-actions a { color: var(--gold-hover) !important; font-weight: 600; }
.iforge-thread-header-actions a:hover { color: #fff !important; }
.iforge-thread-toolbar { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; }
.iforge-thread-toolbar .pagination { font-family: var(--font-sans); font-size: 0.75rem; display: flex; gap: 3px; flex-wrap: wrap; }
.iforge-thread-toolbar .pagination a, .iforge-thread-toolbar .pagination .pagination_current { padding: 3px 8px; background: var(--bg-dark); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-weight: 700; color: var(--ink); text-decoration: none; font-size: 0.72rem; transition: background 0.15s; }
.iforge-thread-toolbar .pagination .pagination_current { background: var(--panel); color: var(--gold); }
.iforge-thread-toolbar .pagination a:hover { background: var(--gold); color: var(--panel); }
.iforge-thread-nav { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; padding: 10px 14px; background: var(--bg-dark); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); font-family: var(--font-sans); font-size: 0.72rem; font-weight: 700; color: var(--ink-secondary); }
.iforge-thread-nav a { color: var(--panel) !important; font-weight: 700; }
.iforge-thread-nav a:hover { color: var(--gold) !important; }
.iforge-thread-tools { font-family: var(--font-sans); font-size: 0.72rem; margin-top: 4px; }
.iforge-thread-tools ul.thread_tools { list-style: none; display: flex; gap: 6px; flex-wrap: wrap; }
.iforge-thread-tools ul.thread_tools li a { padding: 4px 10px; background: var(--panel); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-family: var(--font-sans); font-size: 0.68rem; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: 0.5px; text-decoration: none; display: inline-block; transition: background 0.15s; }
.iforge-thread-tools ul.thread_tools li a:hover { background: var(--gold); color: var(--panel); }
.iforge-postbit { display: flex; gap: 0; background: var(--bg-dark); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); overflow: hidden; margin-bottom: 12px; }
.iforge-postbit:last-child { margin-bottom: 0; }
.iforge-postbit-sidebar { flex: 0 0 170px; display: flex; flex-direction: column; align-items: center; padding: 14px 10px; background: var(--panel); border-right: 3px solid var(--border); gap: 5px; }
.iforge-postbit-avatar { margin-bottom: 4px; }
.iforge-postbit-avatar img { border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); width: 80px; height: 80px; object-fit: cover; }
.iforge-postbit-author { font-family: var(--font-brush); font-size: 1rem; text-transform: uppercase; text-align: center; letter-spacing: 0.8px; line-height: 1.1; word-break: break-word; }
.iforge-postbit-author a { color: var(--gold) !important; text-decoration: none; }
.iforge-postbit-author a:hover { color: var(--gold-hover) !important; }
.iforge-postbit-sidebar .buddy_status { width: 14px; height: 14px; vertical-align: middle; }
.iforge-postbit-badge { font-family: var(--font-sans); font-size: 0.65rem; font-weight: 700; color: var(--gold); text-transform: uppercase; letter-spacing: 0.8px; text-align: center; opacity: 0.85; }
.iforge-postbit-sidebar .star_rating { font-size: 0.6rem; }
.iforge-postbit-sidebar img[src*="groupimages"] { max-width: 80px; height: auto; margin: 2px 0; }
.iforge-postbit-stats { font-family: var(--font-sans); font-size: 0.67rem; color: rgba(255,255,255,0.7); text-align: center; line-height: 1.5; margin-top: 4px; display: flex; flex-direction: column; gap: 1px; }
.iforge-postbit-stats span { display: block; }
.iforge-postbit-body { flex: 1; display: flex; flex-direction: column; padding: 14px; min-width: 0; }
.iforge-postbit-header { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; padding-bottom: 8px; border-bottom: 2px dashed var(--border); margin-bottom: 10px; font-family: var(--font-sans); font-size: 0.72rem; color: var(--ink-secondary); }
.iforge-postbit-header-left { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.iforge-postbit-header-right { display: flex; align-items: center; gap: 6px; }
.iforge-postbit-header img { vertical-align: middle; }
.iforge-postbit-date { font-weight: 600; }
.iforge-postbit-edit { font-style: italic; font-size: 0.68rem; color: var(--ink-secondary); }
.iforge-postbit-edit a { color: var(--panel) !important; font-weight: 600; }
.iforge-postbit-header-right a { color: var(--panel) !important; font-weight: 700; font-size: 0.72rem; }
.iforge-postbit-header-right a:hover { color: var(--gold) !important; }
.iforge-postbit-header-right input.checkbox { vertical-align: middle; margin: 0 0 0 4px; }
.iforge-postbit-content { flex: 1; font-family: var(--font-serif); font-size: 0.95rem; line-height: 1.65; color: var(--ink); overflow-wrap: break-word; word-break: break-word; }
.iforge-postbit-content img { max-width: 100%; height: auto; }
.iforge-postbit-content blockquote { margin: 8px 0; padding: 8px 12px; background: var(--bg); border-left: 3px solid var(--gold); font-size: 0.88rem; }
.iforge-postbit-content blockquote cite { font-family: var(--font-brush); font-size: 0.72rem; color: var(--panel); font-style: normal; }
.iforge-postbit-content .codeblock { margin: 8px 0; padding: 10px 14px; background: var(--panel); color: rgba(255,255,255,0.9); border: 2px solid var(--border); border-radius: var(--radius); font-family: 'Courier New', monospace; font-size: 0.82rem; overflow-x: auto; }
.iforge-postbit-content .mycode_spoiler { margin: 8px 0; }
.iforge-postbit-content .mycode_spoiler .spoiler_header { padding: 6px 10px; background: var(--panel); color: var(--gold); border: 2px solid var(--border); font-family: var(--font-sans); font-size: 0.72rem; font-weight: 700; cursor: pointer; border-radius: var(--radius); }
.iforge-postbit-content .mycode_spoiler .spoiler_body { padding: 8px 10px; background: var(--bg); border: 2px solid var(--border); border-top: none; border-radius: 0 0 var(--radius) var(--radius); }
.iforge-postbit-signature { margin-top: 16px; padding-top: 10px; border-top: 2px dashed var(--border); font-family: var(--font-sans); font-size: 0.75rem; color: var(--ink-secondary); font-style: italic; overflow-wrap: break-word; word-break: break-word; }
.iforge-postbit-signature:empty { display: none; }
.iforge-postbit-meta { font-family: var(--font-sans); font-size: 0.65rem; color: var(--ink-secondary); margin-top: 8px; display: flex; justify-content: space-between; align-items: center; }
.iforge-postbit-actions { display: flex; gap: 5px; margin-top: 12px; padding-top: 10px; border-top: 2px dashed var(--border); flex-wrap: wrap; }
.iforge-postbit-actions a { display: inline-block; padding: 4px 10px; background: var(--panel); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-family: var(--font-sans); font-size: 0.68rem; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: 0.5px; text-decoration: none; cursor: pointer; transition: background 0.15s; white-space: nowrap; }
.iforge-postbit-actions a:hover { background: var(--gold); color: var(--panel); }
.iforge-postbit-actions a span { display: inline; background: none !important; padding: 0 !important; }
.iforge-postbit .ignored_post, .iforge-postbit .deleted_post_collapsed { flex: 1; display: flex; align-items: center; justify-content: center; padding: 24px 14px; font-family: var(--font-sans); font-size: 0.8rem; color: var(--ink-secondary); font-style: italic; gap: 8px; }
.iforge-postbit .ignored_post .button, .iforge-postbit .deleted_post_collapsed .button { padding: 4px 10px; background: var(--panel); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-family: var(--font-sans); font-size: 0.68rem; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: 0.5px; text-decoration: none; cursor: pointer; }
.iforge-postbit .ignored_post .button:hover, .iforge-postbit .deleted_post_collapsed .button:hover { background: var(--gold); color: var(--panel); }
.iforge-postbit .deleted_member_post { padding: 14px; font-family: var(--font-sans); font-size: 0.8rem; color: var(--ink-secondary); font-style: italic; }
.iforge-newreply-btn { display: inline-block; padding: 8px 18px; background: var(--gold); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); font-family: var(--font-brush); font-size: 0.9rem; color: var(--panel); text-transform: uppercase; letter-spacing: 1px; text-decoration: none; cursor: pointer; transition: background 0.15s, transform 0.15s, box-shadow 0.15s; }
.iforge-newreply-btn:hover { background: var(--gold-hover); transform: translateY(-1px); box-shadow: var(--shadow-hover); color: var(--panel); }
.iforge-quickreply { background: var(--bg-dark); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); overflow: hidden; }
.iforge-quickreply-title { font-family: var(--font-brush); font-size: 1.1rem; color: var(--gold); text-transform: uppercase; letter-spacing: 1px; padding: 10px 14px; background: var(--panel); border-bottom: 3px solid var(--border); }
.iforge-quickreply-body { display: flex; gap: 14px; padding: 14px; }
.iforge-quickreply-label { flex: 0 0 180px; font-family: var(--font-sans); font-size: 0.75rem; color: var(--ink); line-height: 1.5; }
.iforge-quickreply-label .smalltext { display: block; font-size: 0.68rem; color: var(--ink-secondary); margin-top: 4px; }
.iforge-quickreply-label label { display: block; margin-top: 6px; font-size: 0.7rem; }
.iforge-quickreply-label input.checkbox { vertical-align: middle; margin-right: 2px; }
.iforge-quickreply-editor { flex: 1; min-width: 0; }
.iforge-quickreply-editor textarea { width: 100%; min-height: 130px; padding: 10px; background: var(--bg); border: 3px solid var(--border); box-shadow: var(--shadow) inset; border-radius: var(--radius); font-family: var(--font-serif); font-size: 0.9rem; color: var(--ink); resize: vertical; }
.iforge-quickreply-actions { padding: 10px 14px; border-top: 2px dashed var(--border); display: flex; gap: 8px; flex-wrap: wrap; }
.iforge-quickreply-submit { padding: 7px 18px; background: var(--gold); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); font-family: var(--font-brush); font-size: 0.85rem; color: var(--panel); text-transform: uppercase; letter-spacing: 0.5px; cursor: pointer; transition: background 0.15s, transform 0.15s; }
.iforge-quickreply-submit:hover { background: var(--gold-hover); transform: translateY(-1px); }
.iforge-quickreply-preview { padding: 7px 18px; background: var(--panel); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); font-family: var(--font-brush); font-size: 0.85rem; color: var(--gold); text-transform: uppercase; letter-spacing: 0.5px; cursor: pointer; transition: background 0.15s, transform 0.15s; }
.iforge-quickreply-preview:hover { background: var(--panel-hover); transform: translateY(-1px); }
.iforge-author-stat { display: block; font-family: var(--font-sans); font-size: 0.67rem; color: rgba(255,255,255,0.7); text-align: center; line-height: 1.4; }
.iforge-thread-container .tborder { background: var(--bg-dark); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); }
.iforge-thread-container .tborder .thead, .iforge-thread-container .tborder .tcat { background: var(--panel); color: var(--gold); border-bottom: 3px solid var(--border); font-family: var(--font-brush); font-size: 1rem; text-transform: uppercase; letter-spacing: 1px; padding: 10px 14px; }
.iforge-thread-container .tborder .trow1, .iforge-thread-container .tborder .trow2 { font-family: var(--font-sans); font-size: 0.78rem; padding: 8px 14px; }
.iforge-thread-container .tborder .tfoot { background: var(--bg-dark); border-top: 3px solid var(--border); padding: 8px 14px; font-family: var(--font-sans); font-size: 0.72rem; }
.iforge-thread-container .modal { display: block !important; background: var(--bg-dark); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); padding: 10px 14px; margin-bottom: 12px; font-family: var(--font-sans); font-size: 0.78rem; color: var(--ink); }
.iforge-thread-container + .float_left { max-width: 1200px; margin: 8px auto 0; padding: 0 16px; font-family: var(--font-sans); font-size: 0.72rem; color: var(--ink-secondary); }

/* ----- RATING ----- */
.iforge-rating { display: flex; justify-content: flex-end; padding: 4px 0; }
.iforge-rating-inner { display: flex; align-items: center; gap: 10px; padding: 6px 12px; background: var(--bg-dark); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-family: var(--font-sans); }
.iforge-rating-label { font-family: var(--font-brush); font-size: 0.75rem; color: var(--panel); text-transform: uppercase; letter-spacing: 0.8px; }
.iforge-rating-stars { display: flex; list-style: none; gap: 2px; margin: 0; padding: 0; position: relative; unicode-bidi: bidi-override; color: var(--ink-secondary); }
.iforge-rating-stars li { display: inline; }
.iforge-rating-current { display: block; position: absolute; top: 0; left: 0; overflow: hidden; white-space: nowrap; color: var(--gold); font-size: 1.2rem; pointer-events: none; }
.iforge-rating-star { color: var(--ink-secondary) !important; font-size: 1.2rem; text-decoration: none; transition: color 0.15s; }
.iforge-rating-star:hover, .iforge-rating-star:hover ~ .iforge-rating-star { color: var(--gold) !important; }

/* ----- SEARCH FORM ----- */
.iforge-search-input { padding: 8px 12px; background: var(--bg); border: 3px solid var(--border); box-shadow: 3px 3px 0 var(--border) inset; border-radius: var(--radius); font-family: var(--font-sans); font-size: 0.78rem; color: var(--ink); outline: none; flex: 1; }
.iforge-search-input:focus { border-color: var(--gold); }
.iforge-search-btn { padding: 8px 14px; background: var(--panel); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); font-family: var(--font-brush); font-size: 0.72rem; color: var(--gold); text-transform: uppercase; letter-spacing: 0.8px; cursor: pointer; transition: background 0.15s; white-space: nowrap; }
.iforge-search-btn:hover { background: var(--panel-hover); }

/* ----- STATUS DOTS ----- */
.iforge-status-dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); vertical-align: middle; }
.iforge-status-online { background: #3cb371; }
.iforge-status-offline { background: #999; }
.iforge-status-away { background: var(--gold); }

/* ----- STATS / REPUTATION / WARNING ----- */
.iforge-stat { display: block; font-family: var(--font-sans); font-size: 0.67rem; color: rgba(255,255,255,0.7); text-align: center; line-height: 1.4; }
.iforge-rep-link { text-decoration: none; }
.iforge-rep-link strong { font-weight: 800; }
.reputation_positive { color: #3cb371; }
.reputation_neutral { color: #999; }
.reputation_negative { color: #c00; }

/* ----- EDITED BY / EDIT REASON ----- */
.iforge-edited { font-style: italic; font-size: 0.68rem; color: var(--ink-secondary); font-family: var(--font-sans); }
.iforge-edited-reason { font-style: italic; color: var(--panel); }
.iforge-editreason { margin-top: 8px; padding: 8px 12px; background: var(--bg); border: 2px solid var(--border); border-radius: var(--radius); }
.iforge-editreason-label { font-family: var(--font-sans); font-size: 0.7rem; font-weight: 700; color: var(--panel); margin-right: 6px; }
.iforge-editreason-input { padding: 4px 8px; background: var(--bg-dark); border: 2px solid var(--border); border-radius: var(--radius); font-family: var(--font-sans); font-size: 0.7rem; color: var(--ink); box-shadow: 2px 2px 0 var(--border) inset; }

/* ----- IP LOGGED ----- */
.iforge-ip { font-family: var(--font-sans); font-size: 0.65rem; color: var(--ink-secondary); }
.iforge-ip a { color: var(--panel); font-weight: 600; }
.iforge-ip a:hover { color: var(--gold); }

/* ----- POST URL / ICON / STATUS ----- */
.iforge-post-url { display: flex; align-items: center; gap: 4px; }
.iforge-post-url a { color: var(--panel); font-weight: 700; text-decoration: none; }
.iforge-post-url a:hover { color: var(--gold); }
.iforge-post-icon { vertical-align: middle; margin-right: 4px; }
.iforge-post-status { font-family: var(--font-sans); font-size: 0.65rem; color: var(--gold); font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; padding: 2px 6px; background: var(--panel); border: 2px solid var(--border); border-radius: var(--radius); }

/* Inline mod checkbox */
.iforge-inline-checkbox { accent-color: var(--gold); width: 14px; height: 14px; vertical-align: middle; margin: 0 0 0 5px; }

/* ----- USER STARS / GROUP IMAGE ----- */
.iforge-star { display: inline-block; vertical-align: middle; }
.iforge-groupimage { max-width: 80px; height: auto; margin: 2px 0; }

/* ----- PROFILE FIELDS ----- */
.iforge-profilefield { display: block; font-family: var(--font-sans); font-size: 0.67rem; color: rgba(255,255,255,0.7); text-align: center; line-height: 1.4; }
.iforge-profilefield-list { list-style: none; margin: 0; padding: 0; }
.iforge-profilefield-item { font-family: var(--font-sans); font-size: 0.67rem; color: rgba(255,255,255,0.7); }

/* Override group username colors in postbit sidebar */
.iforge-postbit-author a span, .iforge-postbit-author a strong, .iforge-postbit-author a * { color: var(--gold) !important; }

@media (max-width: 650px) {
  .iforge-postbit { flex-direction: column; }
  .iforge-postbit-sidebar { flex: 0 0 auto; flex-direction: row; flex-wrap: wrap; justify-content: center; border-right: none; border-bottom: 3px solid var(--border); padding: 10px; gap: 6px; }
  .iforge-postbit-avatar img { width: 48px; height: 48px; }
  .iforge-postbit-author { font-size: 0.85rem; }
  .iforge-postbit-stats { flex-direction: row; gap: 8px; margin-top: 0; width: 100%; justify-content: center; }
  .iforge-postbit-body { padding: 10px; }
  .iforge-quickreply-body { flex-direction: column; gap: 8px; }
  .iforge-quickreply-label { flex: 0 0 auto; }
  .iforge-thread-header { flex-direction: column; align-items: flex-start; }
  .iforge-thread-header .iforge-thread-title { font-size: 1.15rem; }
}

/* ===== POSTING FORMS ===== */
.iforge-form-container { max-width: 1200px; margin: 0 auto; padding: 16px; display: flex; flex-direction: column; gap: 12px; font-family: var(--font-serif); }
.iforge-form-title { font-family: var(--font-brush); font-size: 1.6rem; color: var(--panel); text-transform: uppercase; letter-spacing: 1.5px; text-shadow: 2px 2px 0 var(--gold); margin: 0; }
.iforge-form-card { background: var(--bg-dark); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); padding: 16px; display: flex; flex-direction: column; gap: 14px; }
.iforge-form-field { display: flex; flex-direction: column; gap: 6px; }
.iforge-form-label { font-family: var(--font-brush); font-size: 0.9rem; color: var(--panel); text-transform: uppercase; letter-spacing: 0.8px; }
.iforge-form-subject-row { display: flex; gap: 8px; align-items: center; }
.iforge-form-input, .iforge-form-card input[type="text"] { padding: 10px 12px; background: var(--bg); border: 3px solid var(--border); box-shadow: 3px 3px 0 var(--border) inset; border-radius: var(--radius); font-family: var(--font-serif); font-size: 0.9rem; color: var(--ink); width: 100%; }
.iforge-form-input:focus, .iforge-form-card input[type="text"]:focus { outline: none; border-color: var(--gold); box-shadow: 0 0 0 2px rgba(201,168,76,0.3) inset; }
.iforge-form-editor .sceditor-container { border: 3px solid var(--border) !important; border-radius: var(--radius) !important; box-shadow: var(--shadow); }
.iforge-form-editor .sceditor-container .sceditor-toolbar { background: var(--panel) !important; border-bottom: 3px solid var(--border) !important; }
.iforge-form-editor .sceditor-container textarea, .iforge-form-editor .sceditor-container .sceditor-textarea { background: var(--bg) !important; font-family: var(--font-serif) !important; font-size: 0.9rem !important; color: var(--ink) !important; }
.iforge-form-editor textarea#message { padding: 10px 12px; background: var(--bg); border: 3px solid var(--border); box-shadow: 3px 3px 0 var(--border) inset; border-radius: var(--radius); font-family: var(--font-serif); font-size: 0.9rem; color: var(--ink); width: 100%; max-width: 100%; resize: vertical; }
.iforge-form-editor textarea#message:focus { outline: none; border-color: var(--gold); box-shadow: 0 0 0 2px rgba(201,168,76,0.3) inset; }
.iforge-postoptions-card { background: var(--bg); border: 3px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); padding: 12px 14px; display: flex; flex-wrap: wrap; gap: 14px; align-items: center; font-family: var(--font-sans); font-size: 0.78rem; color: var(--ink); }
.iforge-postoptions-label { font-family: var(--font-brush); font-size: 0.8rem; color: var(--panel); text-transform: uppercase; letter-spacing: 0.8px; }
.iforge-postoptions-card label { display: flex; align-items: center; gap: 4px; font-weight: 600; cursor: pointer; }
.iforge-postoptions-card input[type="checkbox"] { accent-color: var(--gold); }
.iforge-form-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.iforge-form-submit { padding: 8px 20px; background: var(--gold); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-family: var(--font-brush); font-size: 1rem; color: var(--panel); text-transform: uppercase; letter-spacing: 1px; cursor: pointer; transition: background 0.15s, transform 0.15s; }
.iforge-form-submit:hover { background: var(--gold-hover); transform: translateY(-1px); }
.iforge-form-submit-secondary { padding: 8px 16px; background: var(--panel); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-family: var(--font-sans); font-size: 0.72rem; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: 0.5px; cursor: pointer; text-decoration: none; transition: background 0.15s; }
.iforge-form-submit-secondary:hover { background: var(--panel-hover); }
.iforge-threadreview { background: var(--bg-dark); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); padding: 14px; display: flex; flex-direction: column; gap: 10px; }
.iforge-threadreview .iforge-threadreview-title { font-family: var(--font-brush); font-size: 1rem; color: var(--gold); text-transform: uppercase; margin: 0; text-shadow: 2px 2px 0 var(--panel); }
.iforge-threadreview-posts { display: flex; flex-direction: column; gap: 0; }
.iforge-threadreview-post { padding: 10px 0; border-bottom: 2px dashed var(--border); }
.iforge-threadreview-post:last-child { border-bottom: none; padding-bottom: 0; }
.iforge-threadreview-post-author { font-family: var(--font-sans); font-weight: 700; font-size: 0.75rem; color: var(--panel); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 6px; }
.iforge-threadreview-post-body { font-size: 0.82rem; color: var(--ink); line-height: 1.5; }
.iforge-threadreview-more { padding-top: 8px; font-family: var(--font-sans); font-size: 0.75rem; color: var(--gold); text-transform: uppercase; letter-spacing: 1px; border-top: 2px dashed var(--border); }
.iforge-form-card .pollbox, .iforge-form-card form[style] { background: var(--bg); border: 3px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); padding: 12px 14px; font-family: var(--font-sans); font-size: 0.8rem; color: var(--ink); }
.iforge-form-card .posticons, .iforge-form-card tr, .iforge-form-card td { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.iforge-form-card .posticons label { cursor: pointer; }
.iforge-form-card tr, .iforge-form-card td, .iforge-form-card .trow1, .iforge-form-card .trow2, .iforge-form-card .tcat { background: transparent !important; border: none !important; font-family: var(--font-sans); font-size: 0.78rem; color: var(--ink); }
.iforge-form-container .attachbox, .iforge-form-container .tborder { background: var(--bg-dark); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); padding: 14px; }
.iforge-form-container .tborder td, .iforge-form-container .tborder tr { background: transparent !important; font-family: var(--font-sans); font-size: 0.8rem; color: var(--ink); }
.iforge-form-container .thead, .iforge-form-container .tcat { background: var(--panel) !important; color: var(--gold) !important; border: 3px solid var(--border) !important; box-shadow: var(--shadow) !important; font-family: var(--font-brush); font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.8px; }
.iforge-form-container .tfoot { background: var(--panel) !important; color: #fff !important; font-family: var(--font-sans); font-size: 0.75rem; font-weight: 600; }
.iforge-form-container .forumrules { background: var(--bg-dark); border: 3px solid var(--border); box-shadow: var(--shadow); border-radius: var(--radius); padding: 14px; font-size: 0.85rem; color: var(--ink); }
@media (max-width: 600px) {
  .iforge-form-title { font-size: 1.3rem; }
  .iforge-postoptions-card { flex-direction: column; align-items: flex-start; }
  .iforge-form-actions { flex-direction: column; }
  .iforge-form-submit,   .iforge-form-submit-secondary { width: 100%; text-align: center; padding: 10px 16px; }
}

/* ===== FORUMDISPLAY ENHANCED ===== */
.iforge-sort-bar {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding: 0;
}
.iforge-sort-bar select {
  padding: 4px 8px;
  background: var(--panel-hover);
  color: #fff;
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
}
.iforge-sort-bar input.iforge-go-btn {
  padding: 4px 10px;
  background: var(--gold);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-brush);
  font-size: 0.7rem;
  color: var(--panel);
