  cursor: pointer;
  transition: background 0.15s, transform 0.15s;
}
.iforge-sort-bar input.iforge-go-btn:hover {
  background: var(--gold-hover); transform: translateY(-1px);
}

.iforge-order-arrow {
  font-size: 0.78rem; margin-left: 2px; font-weight: 700;
}
.iforge-order-arrow a { color: var(--gold); font-weight: 700; text-decoration: none; }
.iforge-order-arrow a:hover { color: var(--gold-hover); }

.iforge-search-form {
  display: flex; align-items: center; gap: 4px;
}
.iforge-search-form input[type="text"] {
  padding: 4px 8px;
  background: var(--bg-dark);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.7rem;
  color: var(--ink);
}
.iforge-search-form input.iforge-search-submit {
  padding: 4px 10px;
  background: var(--panel);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-brush);
  font-size: 0.68rem;
  color: var(--gold);
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.15s, transform 0.15s;
}
.iforge-search-form input.iforge-search-submit:hover {
  background: var(--panel-hover); transform: translateY(-1px);
}

.iforge-thread-icon-char {
