}
.iforge-rules-card-header {
  padding: 10px 14px;
  background: var(--panel);
  border-bottom: 3px solid var(--border);
  font-family: var(--font-brush);
  font-size: 0.95rem;
  color: var(--gold);
  text-transform: uppercase;
  letter-spacing: 1px;
}
.iforge-rules-card-body {
  padding: 12px 14px;
  font-size: 0.85rem; color: var(--ink); line-height: 1.6;
