}
.iforge-password-card-body {
  padding: 16px;
  font-size: 0.85rem; color: var(--ink);
}
.iforge-password-card-body input[type="password"] {
  width: 100%;
  padding: 8px 10px;
  background: var(--bg);
  border: 3px solid var(--border);
  box-shadow: 3px 3px 0 var(--border) inset;
  border-radius: var(--radius);
  font-family: var(--font-serif);
