}

.iforge-unapproved-badge {
  display: inline-block;
  padding: 1px 6px;
  background: #b42828;
  color: #fff;
  border: 1px solid #7a1a1a;
  border-radius: 2px;
  font-family: var(--font-sans);
  font-size: 0.6rem;
  font-weight: 700;
  margin-left: 3px;
  vertical-align: middle;
}

.iforge-thread-rating { flex-shrink: 0; }
.iforge-thread-rating .star_rating {
  list-style: none; height: 12px; position: relative;
  width: 60px;
}
.iforge-thread-rating .star_rating .current_rating {
  height: 12px; position: absolute; left: 0; top: 0;
}

.iforge-thread-modbit {
  flex-shrink: 0; display: flex; align-items: center; padding-left: 8px;
}
.iforge-thread-modbit input.checkbox { width: 14px; height: 14px; accent-color: var(--gold); cursor: pointer; }

.iforge-sticky-sep {
  border-top: 2px dashed var(--gold);
  margin: 2px 0;
}

.iforge-sub-link {
  display: inline-block;
  padding: 1px 8px;
  background: var(--panel);
  color: var(--gold);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.62rem;
  font-weight: 700;
  text-transform: uppercase;
  text-decoration: none;
  transition: background 0.15s, transform 0.15s;
}
.iforge-sub-link:hover { background: var(--panel-hover); transform: translateY(-1px); }

.iforge-clear-link {
  font-family: var(--font-sans); font-size: 0.68rem; font-weight: 600;
  color: var(--panel); text-decoration: none; text-transform: uppercase;
  padding: 2px 6px; border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius);
  background: var(--bg-dark); display: inline-block;
  transition: background 0.15s, transform 0.15s;
}
.iforge-clear-link:hover { background: var(--gold); color: var(--panel); transform: translateY(-1px); }

.iforge-gotounread {
  font-size: 0.65rem; color: var(--gold); font-weight: 700;
  text-decoration: none; margin-right: 2px;
}
.iforge-gotounread:hover { color: var(--gold-hover); }

/* ===== GLOBAL FORM INPUTS ===== */
select, input[type="text"], input[type="password"], input[type="email"], input[type="number"], textarea {
  padding: 8px 10px;
  background: var(--bg);
  border: 3px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.82rem;
  color: var(--ink);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
select:focus, input[type="text"]:focus, input[type="password"]:focus, input[type="email"]:focus, input[type="number"]:focus, textarea:focus {
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(201,168,76,0.2);
}
input[type="submit"], input[type="button"], button {
  padding: 8px 16px;
  background: var(--panel);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.78rem;
  font-weight: 700;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: background 0.15s, transform 0.15s;
}
input[type="submit"]:hover, input[type="button"]:hover, button:hover {
  background: var(--panel-hover);
  transform: translateY(-1px);
}
input[type="checkbox"] { accent-color: var(--gold); }
input[type="radio"] { accent-color: var(--gold); }

/* ===== POLL FORM ===== */
.iforge-poll-card {
  background: var(--bg);
  border: 3px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-family: var(--font-sans);
  font-size: 0.8rem;
  color: var(--ink);
}
.iforge-poll-desc { color: var(--ink-secondary); font-size: 0.72rem; }
.iforge-poll-check { font-weight: 700; cursor: pointer; display: flex; align-items: center; gap: 4px; }
.iforge-poll-options { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.iforge-poll-options-label { font-weight: 700; color: var(--panel); text-transform: uppercase; font-size: 0.72rem; }
.iforge-poll-max { color: var(--ink-secondary); font-size: 0.7rem; font-style: italic; }
.iforge-poll-input {
  width: 52px;
  padding: 6px 8px;
  background: var(--bg-dark);
  border: 3px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.8rem;
  color: var(--ink);
  text-align: center;
  outline: none;
}
.iforge-poll-input:focus { border-color: var(--gold); }

/* ===== POLL BARS ===== */
.iforge-poll-bar { background: var(--bg); border: 2px solid var(--border); border-radius: var(--radius); height: 22px; overflow: hidden; }
.iforge-poll-fill { background: var(--gold); height: 100%; transition: width 0.3s; }
.iforge-poll-fill-voted { background: var(--panel); }

/* ===== POST ICONS ===== */
.iforge-posticons-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}
.iforge-posticon-item {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 10px;
  background: var(--bg);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  transition: border-color 0.15s, box-shadow 0.15s;
  font-family: var(--font-sans);
  font-size: 0.72rem;
}
.iforge-posticon-item:hover { border-color: var(--gold); }
.iforge-posticon-item input[type="radio"] { margin: 0; accent-color: var(--gold); }
.iforge-posticon-item img { width: 16px; height: 16px; object-fit: contain; }
.iforge-posticon-label { color: var(--ink-secondary); font-weight: 600; font-size: 0.72rem; }

/* ===== CODEBUTTONS / SCEDITOR ===== */
.iforge-codebuttons { margin-top: 6px; }
.iforge-codebuttons .sceditor-container {
  border: 3px solid var(--border) !important;
  border-radius: var(--radius) !important;
  box-shadow: var(--shadow);
  overflow: hidden;
}
.iforge-codebuttons .sceditor-container .sceditor-toolbar {
  background: var(--panel) !important;
  border-bottom: 3px solid var(--border) !important;
  padding: 4px;
}
.iforge-codebuttons .sceditor-container .sceditor-toolbar .sceditor-button {
  background: var(--panel-hover) !important;
  border: 2px solid var(--border) !important;
  box-shadow: 2px 2px 0 rgba(0,0,0,0.2) !important;
  border-radius: var(--radius) !important;
  margin: 2px !important;
}
.iforge-codebuttons .sceditor-container .sceditor-toolbar .sceditor-button:hover,
.iforge-codebuttons .sceditor-container .sceditor-toolbar .sceditor-button.active {
  background: var(--gold) !important;
}
.iforge-codebuttons .sceditor-container textarea,
.iforge-codebuttons .sceditor-container .sceditor-textarea {
  background: var(--bg) !important;
  font-family: var(--font-serif) !important;
  font-size: 0.9rem !important;
  color: var(--ink) !important;
}

/* ===== MULTIQUOTE ===== */
.iforge-multiquote {
  margin-top: 8px;
  padding: 8px 12px;
  background: var(--bg);
  border: 2px dashed var(--gold);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.72rem;
  color: var(--ink);
  font-weight: 600;
}
.iforge-multiquote a { color: var(--panel); font-weight: 700; }
.iforge-multiquote a:hover { color: var(--gold); }

/* ===== REDIRECT ===== */
.iforge-redirect {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 50vh;
  padding: 32px 16px;
}
.iforge-redirect-inner {
  text-align: center;
  max-width: 520px;
  width: 100%;
  background: var(--bg-dark);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  padding: 40px 32px;
}
.iforge-redirect-icon {
  font-size: 3rem;
  color: var(--panel);
  margin-bottom: 12px;
  text-shadow: 2px 2px 0 var(--gold);
}
.iforge-redirect-title {
  font-family: var(--font-brush);
  font-size: 1.75rem;
  color: var(--panel);
  text-transform: uppercase;
  letter-spacing: 1.5px;
  text-shadow: 2px 2px 0 var(--gold);
  margin: 0 0 12px;
  line-height: 1.2;
}
.iforge-redirect-message {
  font-size: 0.9rem;
  color: var(--ink);
  line-height: 1.5;
  margin-bottom: 20px;
}
.iforge-redirect-link {
  display: inline-block;
  padding: 8px 22px;
  background: var(--gold);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-brush);
  font-size: 1rem;
  color: var(--panel);
  text-transform: uppercase;
  letter-spacing: 1px;
  text-decoration: none;
  transition: background 0.15s, transform 0.15s;
}
.iforge-redirect-link:hover { background: var(--gold-hover); transform: translateY(-1px); color: var(--panel); }

/* ===== ERROR PAGES ===== */
.iforge-error-container {
  max-width: 680px;
  margin: 32px auto;
  padding: 0 16px;
}
.iforge-error-card {
  background: var(--bg-dark);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  padding: 36px 32px;
  text-align: center;
}
.iforge-error-icon {
  font-size: 3.5rem;
  color: var(--gold);
  margin-bottom: 12px;
  text-shadow: 2px 2px 0 var(--panel);
}
.iforge-error-title {
  font-family: var(--font-brush);
  font-size: 1.6rem;
  color: var(--panel);
  text-transform: uppercase;
  letter-spacing: 1px;
  text-shadow: 2px 2px 0 var(--gold);
  margin: 0 0 16px;
  line-height: 1.2;
}
.iforge-error-body {
  font-size: 0.9rem;
  color: var(--ink);
  line-height: 1.6;
  text-align: left;
}
.iforge-error-body ul, .iforge-error-body ol { padding-left: 20px; }

.iforge-error-inline {
  background: var(--bg);
  border: 3px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  margin: 8px 0;
  overflow: hidden;
}
.iforge-error-inline-banner {
  background: var(--panel);
  color: var(--gold);
  padding: 8px 14px;
  font-family: var(--font-brush);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  border-bottom: 3px solid var(--border);
}
.iforge-error-inline-body {
  padding: 10px 14px;
  font-family: var(--font-sans);
  font-size: 0.78rem;
  color: var(--ink);
  line-height: 1.6;
}
.iforge-error-inline-body ul { padding-left: 20px; list-style: square; }
.iforge-error-inline-body ul li { margin-bottom: 4px; }

.iforge-error-nopermission {
  padding: 20px 24px;
  font-family: var(--font-sans);
  font-size: 0.85rem;
  color: var(--ink);
  line-height: 1.7;
  text-align: left;
}
.iforge-error-nopermission-icon {
  font-size: 2.5rem;
  margin-bottom: 12px;
  display: block;
}
.iforge-error-nopermission ol { padding-left: 20px; margin: 10px 0; }
.iforge-error-nopermission ol li { margin-bottom: 4px; }
.iforge-error-nopermission a { color: var(--panel); font-weight: 700; }
.iforge-error-nopermission a:hover { color: var(--gold); }
.iforge-error-username { margin-top: 12px; font-weight: 700; color: var(--panel); font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.5px; }

.iforge-error-nopermission-loggedout {
  padding: 20px 24px;
  font-family: var(--font-sans);
  font-size: 0.85rem;
  color: var(--ink);
  line-height: 1.7;
  text-align: left;
}
.iforge-error-nopermission-loggedout-icon {
  font-size: 2.5rem;
  margin-bottom: 12px;
  display: block;
}
.iforge-error-nopermission-loggedout ol { padding-left: 20px; margin: 10px 0; }
.iforge-error-nopermission-loggedout ol li { margin-bottom: 4px; }
.iforge-error-nopermission-loggedout a { color: var(--panel); font-weight: 700; }
.iforge-error-nopermission-loggedout a:hover { color: var(--gold); }

/* ===== GLOBAL CODE / PRE ===== */
pre, .codeblock {
  margin: 8px 0;
  padding: 10px 14px;
  background: var(--panel);
  color: rgba(255,255,255,0.9);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  font-family: 'Courier New', 'Consolas', monospace;
  font-size: 0.82rem;
  overflow-x: auto;
  line-height: 1.45;
}

/* Navigation breadcrumb */
.navigation {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
  font-family: var(--font-sans);
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 4px 0;
}
.navigation a {
  padding: 2px 8px;
  background: var(--panel);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  color: var(--gold);
  text-decoration: none;
}
.navigation a:hover { background: var(--panel-hover); }
.navigation .active { color: var(--ink); font-weight: 700; }
.navigation span { color: var(--ink-secondary); }

@media (max-width: 600px) {
  .iforge-redirect-inner { padding: 28px 18px; }
  .iforge-redirect-title { font-size: 1.3rem; }
  .iforge-error-card { padding: 24px 18px; }
  .iforge-error-title { font-size: 1.3rem; }
  .iforge-posticons-grid { justify-content: center; }
}

.iforge-thread-icon-newfolder .iforge-thread-icon-char { color: var(--panel); }
.iforge-thread-icon-newhotfolder .iforge-thread-icon-char { color: var(--gold); }
.iforge-thread-icon-hotfolder .iforge-thread-icon-char { color: var(--gold-hover); }
.iforge-thread-icon-folder .iforge-thread-icon-char { color: var(--ink-secondary); }
.iforge-thread-icon-closefolder .iforge-thread-icon-char { color: var(--ink-secondary); }
.iforge-thread-icon-dot_folder .iforge-thread-icon-char { color: var(--gold); }

/* ===== NUCLEAR OVERRIDES - flatten all MyBB default styles ===== */
.smalltext, .smalltext *, .iforge-meta-text, .iforge-meta-text * { font-size: 0.72rem; font-family: var(--font-sans); color: var(--ink-secondary); }
.float_left { float: left; margin: 0; }
.float_right { float: right; margin: 0; }
.clear { clear: both; }
.wrapper { max-width: none; width: 100%; margin: 0; padding: 0; }
.navigation { display: flex; align-items: center; gap: 4px; padding: 0; background: none; border: none; font-family: var(--font-sans); font-size: 0.75rem; color: var(--ink-secondary); margin: 0 0 8px 0; }
.navigation a { color: var(--panel); font-weight: 600; }
.navigation .active { color: var(--ink); font-weight: 700; }
.thread_tools { list-style: none; padding: 0; margin: 0; display: flex; gap: 6px; flex-wrap: wrap; }
.thread_tools li { list-style: none; padding: 0; margin: 0; }
.thread_tools a { display: inline-block; padding: 4px 10px; background: var(--panel); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-family: var(--font-sans); font-size: 0.68rem; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: 0.5px; text-decoration: none; transition: background 0.15s; }
.thread_tools a:hover { background: var(--gold); color: var(--panel); }
select, input[type="text"], input[type="password"], input[type="search"], input[type="email"], input[type="number"] { font-family: var(--font-sans); font-size: 0.85rem; }
select { background: var(--bg); border: 2px solid var(--border); color: var(--ink); padding: 4px 8px; border-radius: var(--radius); font-weight: 600; }
input[type="text"], input[type="password"], input[type="search"], input[type="email"] { padding: 8px 12px; background: var(--bg); border: 3px solid var(--border); box-shadow: 2px 2px 0 var(--border) inset; border-radius: var(--radius); color: var(--ink); }
input[type="text"]:focus, input[type="password"]:focus, input[type="search"]:focus, textarea:focus { outline: none; border-color: var(--gold); box-shadow: 0 0 0 2px rgba(201,168,76,0.3) inset; }
textarea { padding: 10px 12px; background: var(--bg); border: 3px solid var(--border); box-shadow: 2px 2px 0 var(--border) inset; border-radius: var(--radius); font-family: var(--font-serif); font-size: 0.9rem; color: var(--ink); }
input[type="checkbox"] { accent-color: var(--gold); }
input[type="radio"] { accent-color: var(--gold); }
input[type="submit"], button, .button { padding: 6px 14px; background: var(--panel); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-family: var(--font-sans); font-size: 0.75rem; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: 0.5px; cursor: pointer; transition: background 0.15s, transform 0.15s; }
input[type="submit"]:hover, button:hover, .button:hover { background: var(--gold); color: var(--panel); transform: translateY(-1px); }
fieldset { border: 3px solid var(--border); border-radius: var(--radius); padding: 12px; margin: 0; }
legend { font-family: var(--font-brush); color: var(--panel); text-transform: uppercase; padding: 0 8px; font-size: 0.85rem; }
dl.thread_legend { display: flex; gap: 12px; flex-wrap: wrap; list-style: none; padding: 0; margin: 0; font-family: var(--font-sans); }
dl.thread_legend dd { margin: 0; display: flex; align-items: center; gap: 4px; font-size: 0.7rem; color: var(--ink-secondary); }
.modal { position: fixed; z-index: 9999; }
#quick_login { display: none !important; }
hr { border: none; border-top: 2px dashed var(--border); margin: 8px 0; }
ol, ul { margin: 0; color: var(--ink); }
pre { background: var(--panel); color: rgba(255,255,255,0.9); border: 2px solid var(--border); border-radius: var(--radius); padding: 12px 14px; font-family: 'Courier New', monospace; font-size: 0.82rem; overflow-x: auto; line-height: 1.4; }
code { font-family: 'Courier New', monospace; background: var(--bg); padding: 2px 6px; border-radius: 2px; font-size: 0.85rem; color: var(--panel); }
blockquote { border-left: 3px solid var(--gold); padding: 8px 12px; margin: 8px 0; background: var(--bg); font-style: italic; }
table { border-collapse: collapse; }
td, th { padding: 8px 12px; text-align: left; }
.tborder, .tcat, .thead, .trow1, .trow2, .tfoot, .trow_sep { background: transparent !important; border-color: var(--border) !important; font-family: var(--font-sans) !important; font-size: inherit !important; color: inherit !important; }
.pagination { display: flex; gap: 3px; flex-wrap: wrap; font-family: var(--font-sans); font-size: 0.75rem; }
.pagination a, .pagination span { padding: 3px 8px; background: var(--bg-dark); border: 2px solid var(--border); box-shadow: 2px 2px 0 var(--border); border-radius: var(--radius); font-weight: 700; color: var(--ink); text-decoration: none; font-size: 0.72rem; }
.pagination .pagination_current { background: var(--panel); color: var(--gold); }
.pagination a:hover { background: var(--gold); color: var(--panel); }
.scaleimages img, .post_body img, .iforge-postbit-content img { max-width: 100%; height: auto; }
.thread_legend .thread_status { display: inline-block; width: 16px; height: 16px; }
.thread_status { background-size: contain; background-repeat: no-repeat; background-position: center; }
.thread_status.newfolder { background: var(--gold); border-radius: 50%; width: 12px; height: 12px; display: inline-block; }
.thread_status.newhotfolder { background: var(--gold-hover); border-radius: 50%; width: 12px; height: 12px; display: inline-block; box-shadow: 0 0 4px var(--gold); }
.thread_status.hotfolder { background: var(--panel); border-radius: 50%; width: 12px; height: 12px; display: inline-block; }
.thread_status.folder { background: var(--ink-secondary); border-radius: 50%; width: 12px; height: 12px; display: inline-block; opacity: 0.5; }
.thread_status.dot_folder { background: var(--gold); border-radius: 50%; width: 12px; height: 12px; display: inline-block; opacity: 0.6; }
.thread_status.closefolder { border: 2px solid var(--ink-secondary); border-radius: 2px; width: 10px; height: 10px; display: inline-block; opacity: 0.5; }
.reputation_neutral, .reputation_positive, .reputation_negative { font-family: var(--font-sans); font-size: 0.75rem; font-weight: 700; }
.reputation_positive { color: var(--panel); }
.reputation_negative { color: #f85149; }
.reputation_neutral { color: var(--ink-secondary); }
.star_rating { color: var(--gold); font-size: 0.8rem; }
.inline_rating { display: flex; gap: 2px; align-items: center; }
.iforge-header-action-text, .iforge-header-action-text a { font-family: var(--font-sans); font-size: 0.72rem; color: var(--ink-secondary); }
.iforge-header-action-text a { color: var(--gold-hover); font-weight: 600; }
.iforge-header-action-text a:hover { color: #fff; }
#iforge-navbar .iforge-nav { max-width: 1200px; margin: 0 auto; display: flex; align-items: center; justify-content: center; height: 56px; padding: 0 16px; position: relative; }
#iforge-navbar .iforge-nav-link { color: #fff; font-family: var(--font-sans); font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; padding: 4px 0; position: relative; }
#iforge-navbar .iforge-nav-link:hover { color: var(--gold-hover); }
#iforge-navbar .iforge-nav-link::after { content: ''; position: absolute; bottom: -4px; left: 0; right: 0; height: 3px; background: var(--gold); transform: scaleX(0); transition: transform 0.2s; }
#iforge-navbar .iforge-nav-link:hover::after { transform: scaleX(1); }
#iforge-navbar .iforge-nav-logo { position: absolute; left: 16px; font-family: var(--font-brush); font-size: 1.4rem; color: var(--gold); letter-spacing: 2px; text-transform: uppercase; text-shadow: 2px 2px 0 var(--border); text-decoration: none; }
#iforge-navbar .iforge-nav-logo:hover { color: var(--gold-hover); }
#iforge-navbar .iforge-nav-right { position: absolute; right: 16px; }
